(() => {'use strict';const icons={cod4:'cod4.png',minecraft:'minecraft.jpg',valheim:'valheim.jpg','7dtd':'7dtd.jpg',forest:'forest.jpg',palworld:'palworld.jpg',zomboid:'zomboid.jpg'};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const api=(location.hostname==='127.0.0.1'?'':'https://yamahost.yamachat.eu')+'/api/yamahost/public/servers';let records=[],lastFetch=0,busy=false,available=false;const expanded=new Set();
function guide(s){const address=esc(s.connection.value);return s.game==='cod4'?'<ol><li>Spusť CoD4 Multiplayer s CoD4X.</li><li>'+ (s.passwordRequired?'Heslo získej od správce a v konzoli zadej <code>/password tvojeHeslo</code>.':'Server nevyžaduje heslo.')+'</li><li>V konzoli zadej <code>/connect '+address+'</code>.</li><li>Hra nabídne potřebný mod.</li></ol>':s.game==='minecraft'?'<p>Minecraft Java → Multiplayer → Přidat server → <strong>'+address+'</strong>. Použij kompatibilní verzi. Osobní herní registrace /register a přihlášení /login jsou oddělené od Portalu; své heslo nikomu neposílej.</p>':s.game==='palworld'?'<p>Join Multiplayer Game → vlož <strong>'+address+'</strong> → '+(s.passwordRequired?'zaškrtni Enter password → Connect → zadej heslo od správce.':'Connect; server nevyžaduje heslo.')+' Další síťový program není potřeba.</p>':s.game==='valheim'?'<p>Ve Valheimu zvol připojení pomocí kódu a vlož <strong>'+address+'</strong>. '+(s.passwordRequired?'Heslo získej od správce.':'')+'</p>':'<p>Připoj se ve hře podle dostupného připojovacího údaje: <strong>'+address+'</strong>. '+(s.passwordRequired?'Server vyžaduje heslo od správce.':'')+'</p>';}
function card(s){const open=expanded.has(s.id);return '<article class="yp-server '+(open?'is-open':'')+'"><button class="yp-server-summary" data-public-toggle="'+esc(s.id)+'" aria-expanded="'+open+'" aria-controls="public-body-'+esc(s.id)+'">'+(icons[s.game]?'<img src="assets/games/'+icons[s.game]+'" width="38" height="38" alt="" loading="lazy">':'<span class="yp-server-icon">▤</span>')+'<span class="yp-server-title"><strong>'+esc(s.name)+'</strong><small>'+esc(s.gameName)+'</small><span class="yp-server-meta">'+(s.map?'◈ '+esc(s.map)+' · ':'')+(s.players===null?'hráči nezjištěni':esc(s.players)+(s.maxPlayers?'/'+s.maxPlayers:''))+' · <span class="yp-server-online">● Online</span>'+(s.passwordRequired?' · 🔒':'')+'</span></span><span class="yp-server-arrow" aria-hidden="true">⌄</span></button><div class="yp-server-body" id="public-body-'+esc(s.id)+'" '+(!open?'inert':'')+'><div><div class="yp-server-detail">'+(s.mode?'<p>Režim: <strong>'+esc(s.mode)+'</strong></p>':'')+(s.version?'<p>Verze: '+esc(s.version)+'</p>':'')+'<p>'+(s.passwordRequired?'🔒 Chráněný heslem – získáš ho od správce.':'Otevřený bez společného hesla.')+'</p><label>'+(s.connection.kind==='join-code'?'Připojovací kód':'Veřejná adresa')+'<input class="yp-server-address" readonly value="'+esc(s.connection.value)+'"></label><div class="yp-server-actions"><button class="secondary" data-public-copy="'+esc(s.id)+'">⧉ Kopírovat '+(s.connection.kind==='join-code'?'kód':'adresu')+'</button>'+(s.game==='cod4'?'<button class="secondary" data-public-command="'+esc(s.id)+'">⌨ Kopírovat připojení</button>':'')+'</div><details><summary>ⓘ Jak se připojit</summary>'+guide(s)+'</details><p class="caption">Hra běží u hostitele. Při jeho odpojení server z přehledu zmizí. Veřejná brána ani tento panel nezapínají cizí servery.</p></div></div></div></article>';}
function markup(full=false){return '<section class="panel yp-public-panel" data-public-panel="'+(full?'all':'compact')+'"><div class="yp-public-heading"><p class="eyebrow">▤ &nbsp; VEŘEJNÉ HERNÍ SERVERY</p><span data-public-count>Načítám…</span></div>'+(full?'<h2>Právě běžící veřejné servery</h2><a href="#domu" class="secondary">← Zpět na hlavní stránku</a><div class="yp-public-filters"><label>Hledat<input data-public-filter="search" type="search" placeholder="Název serveru nebo světa"></label><label>Hra<select data-public-filter="game"><option value="">Všechny hry</option></select></label><label>Mapa / svět<input data-public-filter="map" type="search"></label><label>Režim<input data-public-filter="mode" type="search"></label><label><input data-public-filter="free" type="checkbox"> Jen potvrzená volná místa</label></div>':'')+'<div data-public-list aria-live="polite"><p class="activity-empty">Načítám aktuální stav…</p></div>'+(!full?'<a class="activity-more" href="#verejne-servery">Zobrazit všechny servery →</a>':'')+'<p class="caption" data-public-note>Automatická kontrola každých 15 sekund, jen při otevřené stránce.</p></section>';}
function render(){for(const panel of document.querySelectorAll('[data-public-panel]')){const full=panel.dataset.publicPanel==='all';let list=records;if(full){const read=key=>panel.querySelector('[data-public-filter='+key+']');const includes=(value,query)=>String(value??'').toLocaleLowerCase('cs-CZ').includes(query.toLocaleLowerCase('cs-CZ'));list=list.filter(s=>includes(s.name+' '+(s.map||''),read('search').value)&&(!read('game').value||s.game===read('game').value)&&includes(s.map,read('map').value)&&includes(s.mode,read('mode').value)&&(!read('free').checked||s.players!==null&&s.maxPlayers!==null&&s.players<s.maxPlayers));const select=read('game'),chosen=select.value;select.innerHTML='<option value="">Všechny hry</option>'+[...new Map(records.map(s=>[s.game,s.gameName])).entries()].map(([id,label])=>'<option value="'+esc(id)+'">'+esc(label)+'</option>').join('');select.value=chosen;}panel.querySelector('[data-public-count]').textContent=available?records.length+' online'+(records.length&&records.every(s=>s.players!==null)?' · '+records.reduce((n,s)=>n+s.players,0)+' hráčů':''):'Stav nedostupný';panel.querySelector('[data-public-list]').innerHTML=!available?'<p class="activity-empty">Stav serverů se nepodařilo ověřit. Další kontrola proběhne automaticky.</p>':!list.length?'<p class="activity-empty">'+(full&&records.length?'Žádný server neodpovídá filtrům.':'Momentálně neběží žádný veřejný server.')+'</p>':(full?list:list.slice(0,5)).map(card).join('');}}
function active(){return ['','#domu','#verejne-servery'].includes(location.hash)&&document.visibilityState!=='hidden';}
async function refresh(force=false){if(!active()||busy||!force&&Date.now()-lastFetch<14000)return;busy=true;if(lastFetch&&Date.now()-lastFetch>30000){records=[];available=false;render();}try{const response=await fetch(api,{cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error();const j=await response.json();if(!Array.isArray(j.servers)||j.servers.length>500)throw Error();records=j.servers.filter(s=>s&&/^[a-f0-9-]{36}$/.test(s.id)&&typeof s.name==='string'&&s.name.length<=60&&typeof s.game==='string'&&/^[a-z0-9-]{1,30}$/.test(s.game)&&s.state==='online'&&s.connection&&typeof s.connection.value==='string'&&s.connection.value.length<=150);for(const id of expanded)if(!records.some(s=>s.id===id))expanded.delete(id);available=true;}catch{records=[];available=false;}finally{busy=false;lastFetch=Date.now();render();}}
function mount(){const page=document.querySelector('#page');if(!page)return;if(location.hash==='#verejne-servery'&&!page.querySelector('[data-public-panel="all"]'))page.innerHTML=markup(true);if(['','#domu'].includes(location.hash)){const slot=page.querySelector('#public-servers-slot');if(slot&&!slot.querySelector('[data-public-panel]'))slot.innerHTML=markup();}if(active()){render();void refresh();}}
async function copy(text,button){const field=document.createElement('textarea');field.value=text;field.readOnly=true;field.style.cssText='position:fixed;opacity:0;width:1px;height:1px';button.closest('[data-public-panel]').append(field);field.select();let ok=false;try{ok=document.execCommand('copy');}catch{}if(!ok)try{await navigator.clipboard.writeText(text);ok=true;}catch{}if(ok){field.remove();const label=button.textContent;button.textContent='✓ Zkopírováno';setTimeout(()=>{button.textContent=label;},1800);}else{field.style.cssText='width:100%;min-height:60px';field.focus();field.select();button.textContent='Označeno – zkopíruj Ctrl+C';}}
document.addEventListener('click',event=>{const toggle=event.target.closest('[data-public-toggle]');if(toggle){const id=toggle.dataset.publicToggle,card=toggle.closest('.yp-server'),open=!expanded.has(id);open?expanded.add(id):expanded.delete(id);card.classList.toggle('is-open',open);toggle.setAttribute('aria-expanded',String(open));card.querySelector('.yp-server-body').inert=!open;}const button=event.target.closest('[data-public-copy],[data-public-command]');if(button){const s=records.find(s=>s.id===(button.dataset.publicCopy||button.dataset.publicCommand));if(s)void copy((button.dataset.publicCommand?'/connect ':'')+s.connection.value,button);}});document.addEventListener('input',event=>{if(event.target.matches('[data-public-filter]'))render();});document.addEventListener('change',event=>{if(event.target.matches('[data-public-filter]'))render();});document.addEventListener('error',event=>{if(event.target.matches?.('.yp-server-summary img')){const fallback=document.createElement('span');fallback.className='yp-server-icon';fallback.textContent='▤';event.target.replaceWith(fallback);}},true);document.addEventListener('visibilitychange',()=>{if(active())void refresh(true);});window.addEventListener('hashchange',()=>setTimeout(mount,0));const page=document.querySelector('#page');if(page)new MutationObserver(()=>mount()).observe(page,{childList:true});setInterval(()=>{void refresh();},15000);window.YamaPublicServers={mount,refresh};setTimeout(mount,0);
})();
